// src/views/Navbar.jsx
import React from "react";
import { Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext"; // Import authentication context
import "../styles/navbar.css"; // Import CSS file for styling

const Navbar = () => {
  const { currentUser, isGuest } = useAuth(); // Get user info
  const username = currentUser ? currentUser.displayName || "User" : "User"; // Fallback to "User" if name not available

  return (
    <nav className="navbar">
      <div className="nav-left">
        <Link to="/chat-prompt">Chat Prompt</Link>
        <Link to="/create-invitation">Create Invitation</Link>
        <Link to="/invite-guests">Invite Guests</Link>
      </div>

      <div className="nav-center">
        <h2>Occasio</h2>
      </div>

      <div className="nav-right">
        <span className="user-account"> {username} </span>
        <img src="/public/userlogo.png" alt="User Icon" className="user-icon" />
      </div>
    </nav>
  );
};

export default Navbar;
